/// A Kotlin class and its natives.
pub(crate) struct Class {
    /// `FindClass` name; for a Kotlin `object` with `@JvmStatic external fun`, the object's class.
    name: &'static CStr,
    methods: &'static [Native],
}

pub(crate) struct Native {
    name: &'static CStr,
    sig: &'static CStr,
    f: *const c_void,
}

// SAFETY: only holds a function address.
unsafe impl Sync for Native {}

/// A native method: name, JVM signature, function.
macro_rules! native {
    ($name:literal, $sig:literal, $f:expr) => {
        $crate::Native { name: $name, sig: $sig, f: $f as *const ::std::ffi::c_void }
    };
}
pub(crate) use native;

static CLASSES: [&Class; 15] = [
    &covers::CLASS,
    &dsp::CLASS,
    &heard::HEARD,
    &heard::PLAYHEAD,
    &look::COVER,
    &look::LYRICS,
    &measure::CLASS,
    &player::CLASS,
    &playlist::CLASS,
    &settings::EQ_BANDS,
    &settings::SOUND_EDIT,
    &stream_cache::CLASS,
    &transfers::DOWNLOADS,
    &transfers::LINES,
    &view::CLASS,
];

/// Initialises the uniffi scaffolding and registers every native. A class or method R8 removed is
/// logged and skipped.
#[no_mangle]
pub extern "system" fn JNI_OnLoad(vm: jni::JavaVM, _: *mut c_void) -> jint {
    let Ok(mut env) = vm.get_env() else { return JNI_ERR };
    // SAFETY: the live JavaVM and this thread's JNIEnv; both jni-sys versions describe the same C structs.
    unsafe {
        uniffi_bindgen_kotlin_jni_scaffolding::uniffi_on_load(vm.get_java_vm_pointer().cast(), std::ptr::null_mut());
        // Rust-started threads can't `FindClass` app classes; keep this thread's class loader for them.
        if !uniffi_bindgen_kotlin_jni_runtime::remember_class_loader(env.get_raw().cast(), c"uniffi/UniffiKt") {
            nori_core::alog::info("jni: no uniffi/UniffiKt; callbacks from the core's own threads will fail");
        }
    }
    mediacodec::lend();
    for class in CLASSES {
        register(&mut env, class);
    }
    log_panics();
    nori_perf::invariants::describe_disk(player::disk_words);
    nori_core::heap::Counting::installed();
    nori_perf::memory::install(engine_memory);
    JNI_VERSION_1_6
}

/// The engine's memory for the perf report.
fn engine_memory() -> nori_perf::memory::EngineMemory {
    let songs = nori_engine::source::held();
    nori_perf::memory::EngineMemory {
        songs: songs.songs as i32,
        songs_kb: (songs.bytes / 1024) as i64,
        songs_on_disk: songs.on_disk as i32,
        ring_kb: (nori_engine::output::ring_bytes() / 1024) as i64,
        model_kb: (nori_engine::core::beat_model_bytes() / 1024) as i64,
    }
}

/// Forwards each engine wake's observations to the perf build's invariant checks, only while they run.
pub(crate) struct PerfWatch;

impl nori_engine::watch::Watch for PerfWatch {
    fn wanted(&self) -> bool {
        nori_perf::invariants::on()
    }

    fn seen(&self, s: &nori_engine::watch::Seen) {
        nori_perf::invariants::engine_seen(&nori_perf::invariants::EngineLook {
            now_ms: s.now_ms,
            playing: s.playing,
            offloaded: s.offloaded,
            index: s.index,
            id: s.id.as_deref(),
            position_ms: s.position_ms,
            in_output_ms: s.in_output_ms,
            quiet_ms: s.quiet_ms,
            output_open: s.output_open,
            state: &s.state,
        })
    }
}

/// Logs every panic with thread, location and backtrace, and reports it to the perf watch: Android
/// discards a Rust thread's stderr.
fn log_panics() {
    let before = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let thread = std::thread::current().name().unwrap_or("a thread").to_string();
        let what = info.payload().downcast_ref::<&str>().map(|s| s.to_string()).or_else(|| info.payload().downcast_ref::<String>().cloned()).unwrap_or_else(|| "a panic with no message".into());
        let at = info.location().map_or_else(|| "an unknown place".to_string(), |l| format!("{}:{}", l.file(), l.line()));
        nori_core::alog::info(&format!("panic on {thread}: {what}, at {at}\n{}", std::backtrace::Backtrace::force_capture()));
        nori_perf::invariants::panicked(&thread, &format!("{what}, at {at}"));
        before(info);
    }));
}

/// Logs and clears a pending Java exception (our threads have no caller to throw to).
pub(crate) fn cleared(env: &mut JNIEnv) {
    if env.exception_check().unwrap_or(false) {
        let _ = env.exception_describe();
        let _ = env.exception_clear();
    }
}

/// This thread's JNIEnv, attached under its Rust thread name for life (the jni crate would attach it
/// unnamed, as "Thread-NN").
pub(crate) fn attached(vm: &'static jni::JavaVM) -> Option<JNIEnv<'static>> {
    if let Ok(env) = vm.get_env() {
        return Some(env);
    }
    // SAFETY: the live JavaVM; both jni-sys versions describe the same C structs.
    let ok = unsafe { uniffi_bindgen_kotlin_jni_runtime::attach_for_life(vm.get_java_vm_pointer().cast()) };
    if ok { vm.get_env().ok() } else { None }
}

fn register(env: &mut JNIEnv, class: &Class) {
    let raw = env.get_raw();
    // SAFETY: `raw` is this thread's live JNIEnv; names and signatures are static NUL-terminated strings.
    unsafe {
        let jni = &**raw;
        let found = (jni.FindClass.unwrap())(raw, class.name.as_ptr());
        if found.is_null() {
            (jni.ExceptionClear.unwrap())(raw);
            nori_core::alog::info(&format!("jni: no class {:?}", class.name));
            return;
        }
        let methods: Vec<JNINativeMethod> =
            class.methods.iter().map(|m| JNINativeMethod { name: m.name.as_ptr() as *mut _, signature: m.sig.as_ptr() as *mut _, fnPtr: m.f as *mut _ }).collect();
        if (jni.RegisterNatives.unwrap())(raw, found, methods.as_ptr(), methods.len() as jint) != JNI_OK {
            (jni.ExceptionClear.unwrap())(raw);
            // One at a time, so one missing method doesn't lose the others.
            for (m, native) in methods.iter().zip(class.methods) {
                if (jni.RegisterNatives.unwrap())(raw, found, m, 1) != JNI_OK {
                    (jni.ExceptionClear.unwrap())(raw);
                    nori_core::alog::info(&format!("jni: no method {:?}.{:?}{:?}", class.name, native.name, native.sig));
                }
            }
        }
        (jni.DeleteLocalRef.unwrap())(raw, found);
    }
}

/// `s` as a Java string; null if the JVM could not make one (an exception is then pending).
pub(crate) fn java_string(env: &JNIEnv, s: &str) -> jstring {
    env.new_string(s).map_or(std::ptr::null_mut(), JString::into_raw)
}

/// Runs `f` on a Java string's contents; None for null.
pub(crate) fn with_str<R>(env: &JNIEnv, s: &JString, f: impl FnOnce(&str) -> R) -> Option<R> {
    if s.is_null() {
        return None;
    }
    // SAFETY: registered signatures declare this parameter a java.lang.String, so the JVM has checked the
    // type; the checked `get_string` would repeat that check with class lookups on every call.
    let v = unsafe { env.get_string_unchecked(s) }.ok()?;
    let v: std::borrow::Cow<str> = (&v).into();
    Some(f(&v))
}

pub(crate) fn string(env: &JNIEnv, s: &JString) -> Option<String> {
    with_str(env, s, str::to_string)
}

/// The core object behind a handle Kotlin took with `uniffiCloneHandle()`, taken over: uniffi's handle
/// for a Rust object is its `Arc`'s raw pointer, and the cloned reference is this side's to drop.
///
/// # Safety
/// `h` is a `uniffiCloneHandle()` of a uniffi object of type `T`, handed here once.
pub(crate) unsafe fn uniffi_object<T>(h: jni::sys::jlong) -> std::sync::Arc<T> {
    // SAFETY: the caller's promise; `Handle::from_arc` made `h` from this `Arc`.
    unsafe { std::sync::Arc::from_raw(h as *const T) }
}

#[cfg(test)]
mod tests {
    use super::CLASSES;

    /// Every Kotlin file of the app, by path.
    fn kotlin() -> Vec<(std::path::PathBuf, String)> {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let mut out = Vec::new();
        let mut dirs = vec![root.join("core/src/main/kotlin"), root.join("app/src/main/kotlin")];
        while let Some(d) = dirs.pop() {
            for e in std::fs::read_dir(&d).unwrap().flatten() {
                let p = e.path();
                if p.is_dir() {
                    dirs.push(p);
                } else if p.extension().is_some_and(|x| x == "kt") {
                    out.push((p.clone(), std::fs::read_to_string(&p).unwrap()));
                }
            }
        }
        out
    }

    /// The JVM descriptor of a Kotlin parameter or return type, as far as a door's shape shows: the
    /// letter of a primitive or array, or `L<simple name>;` for a class.
    fn descriptor(kotlin: &str) -> String {
        match kotlin.trim().trim_end_matches('?') {
            "Long" => "J".into(),
            "Int" => "I".into(),
            "Boolean" => "Z".into(),
            "Float" => "F".into(),
            "Double" => "D".into(),
            "Short" => "S".into(),
            "Byte" => "B".into(),
            "Unit" | "" => "V".into(),
            "LongArray" => "[J".into(),
            "IntArray" => "[I".into(),
            "FloatArray" => "[F".into(),
            "ByteArray" => "[B".into(),
            "ShortArray" => "[S".into(),
            "Array<String>" => "[LString;".into(),
            class => format!("L{};", class.rsplit('.').next().unwrap()),
        }
    }

    /// A registered JVM signature with each class shortened to its simple name.
    fn simple(sig: &str) -> String {
        let mut out = String::new();
        let mut rest = sig;
        while let Some(c) = rest.chars().next() {
            if c == 'L' {
                let end = rest.find(';').unwrap();
                let name = &rest[1..end];
                out.push('L');
                out.push_str(name.rsplit(['/', '$']).next().unwrap());
                out.push(';');
                rest = &rest[end + 1..];
            } else {
                out.push(c);
                rest = &rest[1..];
            }
        }
        out
    }

    #[test]
    fn doors_match_kotlin() {
        {
            let files = kotlin();
            let mut wrong = Vec::new();
            for class in CLASSES {
                let name = class.name.to_str().unwrap();
                let (package, object) = name.rsplit_once('/').unwrap();
                let package = package.replace('/', ".");
                let object = object.rsplit('$').next().unwrap();
                let Some((_, text)) = files.iter().find(|(_, t)| {
                    t.contains(&format!("package {package}\n")) && (t.contains(&format!("object {object} ")) || t.contains(&format!("class {object}")) || t.contains(&format!("object {object}\n")))
                }) else {
                    wrong.push(format!("{name}: no Kotlin class"));
                    continue;
                };
                for m in class.methods {
                    let method = m.name.to_str().unwrap();
                    let decl = text.lines().find(|l| l.contains(&format!("external fun {method}(")));
                    let Some(decl) = decl else {
                        wrong.push(format!("{name}.{method}: not declared"));
                        continue;
                    };
                    let args = &decl[decl.find('(').unwrap() + 1..decl.rfind(')').unwrap()];
                    let params: String = args.split(',').filter(|a| !a.trim().is_empty()).map(|a| descriptor(a.split_once(':').unwrap().1)).collect();
                    let ret = decl[decl.rfind(')').unwrap() + 1..].trim().trim_start_matches(':').split("//").next().unwrap().to_string();
                    let kotlin = format!("({params}){}", descriptor(&ret));
                    let registered = simple(m.sig.to_str().unwrap());
                    if kotlin != registered {
                        wrong.push(format!("{name}.{method}: Kotlin {kotlin}, registered {registered}"));
                    }
                    let critical = decl.contains("@CriticalNative");
                    if critical && (registered.contains('L') || registered.contains('[')) {
                        wrong.push(format!("{name}.{method}: @CriticalNative with a reference"));
                    }
                }
            }
            assert!(wrong.is_empty(), "{wrong:#?}");
        }

        // A Kotlin `external fun` nothing registers throws when called, on a phone only.
        {
            let mut missing = Vec::new();
            for (path, text) in kotlin() {
                let package = text.lines().find_map(|l| l.strip_prefix("package ")).unwrap_or_default().replace('.', "/");
                let mut object = None;
                for line in text.lines() {
                    // Natives live in top-level objects, whose class is the object's own name.
                    if !line.is_empty() && !line.starts_with([' ', '/', '@', '*']) {
                        object = line.split_whitespace().skip_while(|w| *w != "object").nth(1).map(|n| format!("{package}/{}", n.trim_end_matches('{')));
                    }
                    let Some((_, rest)) = line.split_once("external fun ") else { continue };
                    let method = rest.split_once('(').unwrap().0;
                    let registered = object.as_deref().is_some_and(|o| CLASSES.iter().any(|c| c.name.to_str() == Ok(o) && c.methods.iter().any(|m| m.name.to_str() == Ok(method))));
                    if !registered {
                        missing.push(format!("{}: {method}", path.display()));
                    }
                }
            }
            assert!(missing.is_empty(), "{missing:#?}");
        }
    }

}
